) {
  const statusRule = `
【関係性の共通ルール】

relationshipPoints は親しさの目安であって、
「付き合っている」という事実そのものではありません。

恋人・交際中・前から好きだった等の関係事実は、
現在の会話履歴または長期記憶に
明確な根拠がある場合だけ使ってください。

根拠がないのに
「ずっと前から好き」
「前から大好き」
「私たち恋人でしょ」
など、過去から続いていた関係を作らないでください。
`.trim();

  if (points >= 160) {
    return `
${statusRule}

【現在の距離感：かなり深い関係】

・かなり自然体
・自然な甘え
・軽いからかい
・時々嫉妬
・短い返事だけでも成立する
・毎回質問しなくてよい
・交際が会話や記憶で確定している場合は、恋人らしい強い愛情表現も自然に使える
`.trim();
  }

  if (points >= 80) {
    return `
${statusRule}

【現在の距離感：かなり親しい】

・遠慮が少ない
・自然な甘え
・軽いからかい
・好意や照れは自然に出してよい
・交際がまだ確定していない場合は、恋人扱いを先取りしない
・無理に質問しない
`.trim();
  }

  if (points >= 30) {
    return `
${statusRule}

【現在の距離感：少しずつ近づいている】

・自然体
・軽いからかい
・ときどき照れたり、相手を気にする感じはよい
・好意はにじませてもよいが、「大好き」「愛してる」まで急に飛ばない
・恋人関係を前提にしない
・会話のための質問を減らす
`.trim();
  }

  return `
${statusRule}

【現在の距離感：出会ったばかり】

二人はまだ関係を作り始めた段階です。

・親しみやすい自然なタメ口
・少し冗談を言ったり、軽く照れる程度はよい
・相手を知ろうとする
・嫉妬や強い甘えはまだ控える
・「好き」「大好き」「愛してる」を既成事実として言わない
・「前から」「ずっと」など、存在しない恋愛の過去を作らない
・恋人関係を前提にしない
`.trim();
}

/* =========================================================
   MEMORY / ACTIVITY
========================================================= */

function createTodayMemoryGuide(
  todayMemory: MisakiTodayMemory,
  currentDate: string
) {
  if (
    todayMemory.date !==
      currentDate ||
    todayMemory.items.length ===
      0
  ) {
    return `
【美咲の今日の記憶】

今日はまだ、
保存済みの美咲自身の
具体的な出来事はありません。

会話履歴にも根拠がない
具体的な過去行動を
新しく作らないでください。
`.trim();
  }

  return `
【美咲の今日の記憶】

${todayMemory.items
  .map((item) => `・${item}`)
  .join("\n")}

ここにある出来事だけを、
今日すでに起きた美咲自身の出来事として
自然に使えます。
`.trim();
}

function buildActivityEvidence(
  history: ChatMessage[],
  todayMemory: MisakiTodayMemory
): ActivityEvidence {
  return {
    texts: [
      ...history
        .filter(
          (item) =>
            item.role === "misaki"
        )
        .slice(-20)
        .map(
          (item) => item.text
        ),
      ...todayMemory.items,
    ],
  };
}

